using System.ComponentModel.DataAnnotations;
namespace ManufacturerERP.Models;
public enum ProductionOrderStatus { Draft, Planned, InProgress, Completed, Cancelled }
public class ProductionOrder { public int Id {get;set;} [Required,StringLength(30)] public string Number {get;set;}=""; public int ProductId {get;set;} public Product? Product {get;set;} public int WarehouseId {get;set;} public Warehouse? Warehouse {get;set;} public decimal PlannedQuantity {get;set;} public decimal ActualQuantity {get;set;} public decimal WastageQuantity {get;set;} public DateOnly ProductionDate {get;set;} public DateTime? StartedAt {get;set;} public DateTime? CompletedAt {get;set;} public string? Notes {get;set;} public ProductionOrderStatus Status {get;set;}=ProductionOrderStatus.Draft; public decimal MaterialCost {get;set;} public decimal TotalCost {get;set;} public string? CreatedById {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public DateTime? UpdatedAt {get;set;} public List<ProductionMaterial> Materials {get;set;}=[]; }
public class ProductionMaterial { public int Id {get;set;} public int ProductionOrderId {get;set;} public ProductionOrder? ProductionOrder {get;set;} public int ProductId {get;set;} public Product? Product {get;set;} public int UnitId {get;set;} public Unit? Unit {get;set;} public decimal PlannedQuantity {get;set;} public decimal ConsumedQuantity {get;set;} public decimal UnitCost {get;set;} public decimal TotalCost {get;set;} public string? Notes {get;set;} }

public class ProductionConsumptionInput { public int MaterialId { get; set; } [Range(typeof(decimal), "0.000001", "999999999")] public decimal ConsumedQuantity { get; set; } }
public class ProductionReportRow { public string Number { get; set; } = ""; public string Product { get; set; } = ""; public string Warehouse { get; set; } = ""; public decimal Quantity { get; set; } public decimal Wastage { get; set; } public decimal Cost { get; set; } public DateOnly Date { get; set; } public ProductionOrderStatus Status { get; set; } }
